import { useState } from "react";
function Brouillon({ titre }) {
  const [texte, setTexte] = useState("");
  return <label>{titre}<input value={texte} onChange={e => setTexte(e.target.value)} /></label>;
}
export default function App() {
  const [id, setId] = useState(1);
  return <main><button onClick={() => setId(id === 1 ? 2 : 1)}>Autre livre</button>
    <Brouillon key={id} titre={`Livre ${id}`} /></main>;
}
